const route = $('Resolve Doctor Message Route').first().json;
const response = $json;
const errorMessage = response.error?.message || response.error || null;
const providerMessageId = response.id || response.messageId || response.threadId || null;
return [{ json: {
  ...route,
  delivery_status: errorMessage ? 'FAILED' : 'SENT',
  provider_message_id: providerMessageId ? String(providerMessageId) : null,
  error_message: errorMessage ? String(errorMessage) : null
} }];

return $input.all().map(({ json }) => ({ json: {
  ...json,
  delivery_status: 'FAILED',
  provider_message_id: null,
  error_message: json.routing_status === 'ADAPTER_UNAVAILABLE'
    ? `The ${json.channel} communication adapter is not configured.`
    : 'No deliverable recipient was found for this doctor.'
} }));

// Branded doctor email: Apex logo, simple letter wording, one clear button per link, and the mission line.
// Senders pass email_json ({ greeting, intro[], items[{ title, url, button }], after[], links[{ label, url }] });
// without it the plain-text wording is sent as simple HTML (Gmail always sends HTML). **text** marks bold (for dates).
const route = $json;
const input = $('Receive Doctor Message Internally').first().json;
let layout = null;
try { layout = input.email_json ? JSON.parse(input.email_json) : null; } catch { layout = null; }
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
if (!layout || typeof layout !== 'object') {
  const text = String(route.message_text ?? '') + (route.action_url ? '\n\n' + route.action_url : '');
  const linked = esc(text).replace(/https:\/\/[^\s<]+?(?=&quot;|&#39;|&lt;|&gt;|[\s<]|$)/g, (url) => '<a href="' + url + '">' + url + '</a>').replace(/\r?\n/g, '<br>');
  return [{ json: { ...route, message_html: '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222222;">' + linked + '</div>' } }];
}
const rich = (value) => esc(value).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
const safeUrl = (value) => /^https:\/\/[^\s"'<>]+$/.test(String(value || '')) ? String(value) : '';
const list = (value) => (Array.isArray(value) ? value : []).filter((entry) => entry !== null && entry !== undefined && String(entry).trim() !== '');
const font = "'Montserrat','Segoe UI',Helvetica,Arial,sans-serif";
const logo = 'https://apex-content-interviewer.jdold.workers.dev/brand/email-logo.png';
const p = (html) => '<p style="margin:0 0 14px;">' + html + '</p>';
const items = list(layout.items).map((item) => ({ title: String(item.title || ''), url: safeUrl(item.url), button: String(item.button || 'Open') }))
  .filter((item) => item.url);
if (!items.length && list(layout.items).length) throw new Error('The email has a button without a valid secure link.');
let body = p(esc(layout.greeting || 'Hello,'));
for (const line of list(layout.intro)) body += p(rich(line));
for (const item of items) {
  if (item.title) body += '<p style="margin:4px 0 8px;font-weight:700;color:#064C78;">' + esc(item.title) + '</p>';
  body += '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px;"><tr><td bgcolor="#064C78" style="border-radius:6px;">'
    + '<a href="' + esc(item.url) + '" style="display:inline-block;padding:12px 24px;font-family:' + font + ';font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">' + esc(item.button) + '</a></td></tr></table>';
}
for (const line of list(layout.after)) body += p(rich(line));
for (const link of list(layout.links)) {
  const url = safeUrl(link.url);
  if (url) body += p('<a href="' + esc(url) + '" style="color:#064C78;font-weight:700;">' + esc(link.label || url) + '</a>');
}
const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>' + esc(route.subject) + '</title></head>'
  + '<body style="margin:0;padding:0;background:#f4f6f8;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f6f8;"><tr><td align="center" style="padding:28px 12px;">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:100%;background:#ffffff;border:1px solid #e1e7ec;border-radius:10px;">'
  + '<tr><td style="padding:28px 32px 4px;"><img src="' + logo + '" width="150" height="40" alt="Apex Dental Partners" style="display:block;width:150px;height:auto;border:0;"></td></tr>'
  + '<tr><td style="padding:20px 32px 0;font-family:' + font + ';font-size:15px;line-height:1.65;color:#30302F;">' + body
  + '<p style="margin:8px 0 0;">Thank you,<br><b>Apex Content Team</b></p></td></tr>'
  + '<tr><td style="padding:24px 32px 26px;"><div style="border-top:1px solid #e1e7ec;padding-top:16px;text-align:center;font-family:' + font + ';">'
  + '<p style="margin:0 0 6px;font-size:12px;line-height:1.5;font-style:italic;color:#064C78;">Reimagining dentistry to change the lives of our patients, teammates, and the communities we serve.</p>'
  + '<p style="margin:0;font-size:10px;font-weight:700;letter-spacing:1.5px;color:#0092C9;">PRIVATE PRACTICE REIMAGINED&reg;</p></div></td></tr>'
  + '</table></td></tr></table></body></html>';
return [{ json: { ...route, message_html: html } }];
